// Keep only what the outcome check needs from each delivery row.
const byId = {};
for (const item of items) {
  const n = item.json;
  const id = String(n.nudge_id || '');
  if (id) byId[id] = { action_text: String(n.action_text || ''), message_body: String(n.message_body || ''), prescription_id: String(n.prescription_id || '') };
}
return [{ json: { nudges: byId } }];

// Decide, for every schedule_state row, whether it needs an outcome check sent
// or a window closed. One pass, three mutually exclusive jobs, so a row can
// never be both sent to and expired in the same tick.
const users = $('Aggregate Users').first().json.users;
const nudges = $('Aggregate Nudges').first().json.nudges;
const userById = new Map(users.map(u => [String(u.user_id), u]));

const text = v => String(v == null ? '' : v).trim();
const instant = v => { const ms = Date.parse(text(v)); return Number.isFinite(ms) ? ms : null; };
const now = $now.setZone('Australia/Melbourne');
const nowMs = now.toMillis();
const phoneRe = /^\+[1-9]\d{7,14}$/;
const outcomeWindowHours = Number($env.FOLLOWUP_OUTCOME_WINDOW_HOURS || 24);
const HOUR_MS = 3600000;

const out = [];
for (const item of items) {
  const s = item.json;
  const status = text(s.status);
  const nudgeId = text(s.nudge_id);
  if (!nudgeId) continue;

  // Stage 1 expired. Deliberately reuses followup_due_at rather than a second
  // window: if the patient has not committed by the time the check would have
  // gone out, there is nothing left to check on.
  if (status === 'awaiting_commitment' && !text(s.commitment_response)) {
    const due = instant(s.followup_due_at);
    if (due != null && due <= nowMs) {
      out.push({ json: { job: 'expire_commitment', nudge_id: nudgeId, user_id: text(s.user_id) } });
    }
    continue;
  }

  if (status !== 'awaiting_followup') continue;

  // Stage 2 already sent: either still open, or expired unanswered.
  if (text(s.followup_sent_at) || text(s.followup_wa_id)) {
    const sent = instant(s.followup_sent_at);
    if (!text(s.outcome_response) && sent != null && sent + outcomeWindowHours * HOUR_MS <= nowMs) {
      out.push({ json: { job: 'expire_outcome', nudge_id: nudgeId, user_id: text(s.user_id) } });
    }
    continue;
  }

  // Stage 2 not yet sent. Every guard is independent so STOP breaking any one of
  // them is enough, and followup_sent_at above is the claim that makes a
  // duplicate scheduler execution a no-op.
  if (text(s.commitment_response) !== 'YES') continue;
  if (text(s.outcome_response)) continue;
  const due = instant(s.followup_due_at);
  if (due == null || due > nowMs) continue;

  const user = userById.get(text(s.user_id));
  if (!user || text(user.user_status) !== 'active') continue;
  const phone = text(user.phone);
  if (!phoneRe.test(phone)) continue;

  const nudge = nudges[nudgeId] || {};
  const action = text(nudge.action_text);
  if (!action) continue;

  out.push({ json: {
    job: 'send',
    nudge_id: nudgeId,
    schedule_id: text(s.schedule_id) || 'sch_' + nudgeId,
    user_id: text(s.user_id),
    parent_nudge_id: text(s.parent_nudge_id) || nudgeId,
    recipient_phone: phone,
    recipient_name: text(user.name) || 'there',
    action_text: action,
    followup_due_at: text(s.followup_due_at)
  } });
}
return out;

// Build the delayed outcome check. Separate Content Template from the initial
// nudge: its buttons are Done / Not yet, and its text asks about an action the
// patient already committed to.
const sid = String($env.TWILIO_ACCOUNT_SID || '').trim();
const token = String($env.TWILIO_AUTH_TOKEN || '').trim();
const from = String($env.TWILIO_WHATSAPP_FROM || '').trim();
const contentSid = String($env.TWILIO_OUTCOME_CONTENT_SID || '').trim();
if (!sid || !token) throw new Error('Missing Twilio account credentials');
if (!/^whatsapp:\+[1-9]\d{7,14}$/.test(from)) throw new Error('TWILIO_WHATSAPP_FROM must use whatsapp:+E164 format');
if (!/^HX[a-fA-F0-9]{32}$/.test(contentSid)) throw new Error('Missing or invalid TWILIO_OUTCOME_CONTENT_SID');
const authorization = 'Basic ' + Buffer.from(sid + ':' + token).toString('base64');
const encodeForm = pairs => pairs.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');

return items.map(item => {
  const n = item.json;
  const contentVariables = JSON.stringify({
    1: String(n.recipient_name || 'there').trim() || 'there',
    2: String(n.action_text || '').trim()
  });
  const pairs = [
    ['From', from],
    ['To', 'whatsapp:' + n.recipient_phone],
    ['ContentSid', contentSid],
    ['ContentVariables', contentVariables]
  ];
  return { json: { ...n, twilio_url: 'https://api.twilio.com/2010-04-01/Accounts/' + sid + '/Messages.json', twilio_authorization: authorization, twilio_form: encodeForm(pairs), twilio_mode: 'outcome_check' } };
});

// Merge Twilio's response back so the claim can be written with the real SID.
const requests = $('Build Outcome Requests').all();
const sentAt = $now.setZone('Australia/Melbourne').toISO();
return items.map((responseItem, i) => {
  const request = requests[i] ? requests[i].json : {};
  const response = responseItem.json || {};
  if (!response.sid) throw new Error('Twilio response missing Message SID for nudge_id ' + request.nudge_id);
  return { json: { ...request, followup_wa_id: response.sid, followup_sent_at: sentAt } };
});
